/* FORGE photorealistic illustration batch 1.
   Own exercise-specific image triples for Arnold Press, Bird Dog, Hip Thrust, Pallof Press.
   Keep all legacy photo assets and all remaining atlas entries unchanged.
   Generated visuals provide guidance, not medical/instructional certainty.
*/
(function(){
 'use strict';
 const photos={"Arnold Press":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Bird Dog":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Hip Thrust":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Pallof Press":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
 const names=Object.keys(photos);
 const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const oldAtlas=window.forgeExerciseIllustrations;
 const oldPublic=window.forgePublicExercisePictures;
 function picture(name){
   const seq=photos[name];if(!seq)return '';
   const captions=['1 · Startposition','2 · Endposition','3 · Beanspruchte Muskeln'];
   return '<div class="forge165-photo-grid" data-forge165-photo="'+safe(name)+'">'+seq.map((src,i)=>
    '<figure class="forge165-photo"><img loading="lazy" decoding="async" src="'+src+'" alt="'+safe(name)+' – '+safe(captions[i])+'"><figcaption>'+captions[i]+'</figcaption></figure>'
   ).join('')+'</div><p class="forge165-photo-footnote">Ausführung und beteiligte Muskeln anhand der Anleitung prüfen. Die Fotos zeigen beispielhafte Bewegungspositionen.</p>';
 }
 window.forgeExerciseIllustrations=function(name){
   return photos[name]?picture(name):(typeof oldAtlas==='function'?oldAtlas(name):'');
 };
 // Native legacy catalog uses this renderer. Return only these four photo triples,
 // delegate to atlas or older photo library for all other exercises.
 window.forgePublicExercisePictures=function(name){
   return photos[name]?picture(name):(typeof oldPublic==='function'?oldPublic(name):'');
 };
 function style(){
   if(document.getElementById('forge165PhotoCss'))return;
   const s=document.createElement('style');s.id='forge165PhotoCss';
   s.textContent=`
    .forge165-photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:10px 0 13px}
    .forge165-photo{margin:0;min-width:0;background:#1e292d;border:1px solid #38514b;border-radius:12px;overflow:hidden}
    .forge165-photo img{width:100%;height:auto;display:block;aspect-ratio:1.95/1;object-fit:cover;background:#192025}
    .forge165-photo:last-child{grid-column:1/-1}
    .forge165-photo:last-child img{aspect-ratio:2.1/1;object-fit:contain;background:#141c22;max-height:220px}
    .forge165-photo figcaption{padding:7px 8px 9px;color:#dcebe6;text-align:center;font-size:12px;font-weight:700}
    .forge165-photo-footnote{font-size:11px!important;line-height:1.5!important;color:#a4b7b4!important;margin:6px 0 12px!important}
    .forge-strength-body:has(.forge165-photo-grid) > .forge159-muscles,
    .forge-strength-body:has(.forge165-photo-grid) > .forge-muscle-map{display:none!important}
    @media(min-width:650px){.forge165-photo-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.forge165-photo:last-child{grid-column:auto}}
   `;
   document.head.appendChild(s);
 }
 window.forge165BatchInfo={names,picture};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',style,{once:true});else style();
})();